}

function ensureRange(startDate, endDate) {
  if (!isLocalDate(startDate) || !isLocalDate(endDate)) throw new Error('Choose a valid start and end date.');
  if (startDate > endDate) throw new Error('The start date must be on or before the end date.');
}

export function defaultInsightsRange(today = new Date()) {
  const end = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const start = new Date(end);
  start.setDate(start.getDate() - 6);
  return { startDate: localToday(start), endDate: localToday(end) };
}

export function summarizeFocusHistory(history, { startDate, endDate }) {
  ensureRange(startDate, endDate);
  if (!Array.isArray(history)) throw new Error('Focus history must be a list.');
  const taskTotals = new Map();
  let focusedMilliseconds = 0;
  let sessionCount = 0;
  for (const record of history) {
    const localDate = localDateFromTimestamp(record.endedAt);
    if (localDate < startDate || localDate > endDate) continue;
    focusedMilliseconds += record.focusedMilliseconds;
    sessionCount += 1;
    const current = taskTotals.get(record.taskId) ?? { taskId: record.taskId, taskTitle: record.taskTitle, focusedMilliseconds: 0, sessionCount: 0 };
    current.focusedMilliseconds += record.focusedMilliseconds;
    current.sessionCount += 1;
    taskTotals.set(record.taskId, current);
  }
  const tasks = [...taskTotals.values()].sort((first, second) => second.focusedMilliseconds - first.focusedMilliseconds
    || second.sessionCount - first.sessionCount || first.taskTitle.localeCompare(second.taskTitle));
  return { startDate, endDate, focusedMilliseconds, sessionCount, tasks };
}

export function formatInsightsDuration(milliseconds) {
  const wholeMinutes = Math.floor(Math.max(0, milliseconds) / 60_000);
  const hours = Math.floor(wholeMinutes / 60);
  const minutes = wholeMinutes % 60;
  return hours ? `${hours}h ${minutes}m` : `${minutes}m`;
}

export function formatInsightsPercentage(part, total) {
  if (total <= 0) return '0%';
  return `${Math.round((part / total) * 100)}%`;
}

function csvCell(value) {
  return `"${String(value).replaceAll('"', '""')}"`;
}

export function insightsCsv(summary) {
  const rows = [
    ['Start date', 'End date', 'Task name', 'Focused milliseconds', 'Focused time', 'Session count'],
    ...summary.tasks.map(task => [summary.startDate, summary.endDate, task.taskTitle, task.focusedMilliseconds, formatInsightsDuration(task.focusedMilliseconds), task.sessionCount])
  ];
  return `${rows.map(row => row.map(csvCell).join(',')).join('\r\n')}\r\n`;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { defaultInsightsRange, formatInsightsDuration, formatInsightsPercentage, insightsCsv, summarizeFocusHistory } from '../src/insights.js';

const history = [
  { id: 'one', taskId: 'task-a', taskTitle: 'Draft, review "notes"', focusedMilliseconds: 1_500_000, endedAt: '2026-09-20T00:30:00.000Z' },
  { id: 'two', taskId: 'task-a', taskTitle: 'Draft, review "notes"', focusedMilliseconds: 600_000, endedAt: '2026-09-22T14:00:00.000Z' },
  { id: 'three', taskId: 'task-b', taskTitle: 'Send update', focusedMilliseconds: 900_000, endedAt: '2026-09-24T23:30:00.000Z' },
  { id: 'outside', taskId: 'task-c', taskTitle: 'Outside range', focusedMilliseconds: 1_200_000, endedAt: '2026-09-25T00:01:00.000Z' }
];

test('uses the inclusive local end-date range and aggregates actual focused time by task', () => {
  const summary = summarizeFocusHistory(history, { startDate: '2026-09-20', endDate: '2026-09-24' });
  assert.equal(summary.focusedMilliseconds, 3_000_000);
  assert.equal(summary.sessionCount, 3);
  assert.deepEqual(summary.tasks, [
    { taskId: 'task-a', taskTitle: 'Draft, review "notes"', focusedMilliseconds: 2_100_000, sessionCount: 2 },
    { taskId: 'task-b', taskTitle: 'Send update', focusedMilliseconds: 900_000, sessionCount: 1 }
  ]);
  assert.equal(formatInsightsDuration(summary.focusedMilliseconds), '50m');
  assert.equal(formatInsightsPercentage(summary.tasks[0].focusedMilliseconds, summary.focusedMilliseconds), '70%');
});

test('returns a clear zero summary for an empty selected range', () => {
  const summary = summarizeFocusHistory(history, { startDate: '2026-08-01', endDate: '2026-08-07' });
  assert.deepEqual(summary.tasks, []);
  assert.equal(summary.focusedMilliseconds, 0);
  assert.equal(summary.sessionCount, 0);
  assert.equal(formatInsightsPercentage(0, 0), '0%');
});

test('uses seven inclusive local calendar days and rejects backwards ranges', () => {
  assert.deepEqual(defaultInsightsRange(new Date(2026, 8, 24, 21)), { startDate: '2026-09-18', endDate: '2026-09-24' });
  assert.throws(() => summarizeFocusHistory(history, { startDate: '2026-09-25', endDate: '2026-09-24' }), /start date/);
});

test('exports the selected range and safely escapes commas and quotes in task names', () => {
  const summary = summarizeFocusHistory(history, { startDate: '2026-09-20', endDate: '2026-09-24' });
